export const scenarioIds = ['start', 'rumor', 'old-sighting', 'community'];

export function comparisonState(id) {
  if (!scenarioIds.includes(id)) throw new RangeError('Unknown comparison scenario');
  const { world, ...fields } = initial;
  const state = { ...structuredClone(fields), world };
  if (id === 'start') return state;

  state.day = 9;
  const last = world.road[10], now = world.road[15];
  const patrol = { id: 'comparison-patrol', kind: 'patrulha', ...now, i: 15, dir: 1, men: 9 };
  state.patrols = [patrol];
  state.intel = { known: {}, reports: [], n: 0 };
  if (id === 'rumor') {
    state.intel.n = 1;
    state.intel.reports.push({ id: 1, kind: patrol.kind, ...world.road[14], r: 130,
      seen: 8, got: 9, src: 'rumor', rel: 'fraca', fid: patrol.id });
  }
  if (id === 'old-sighting') {
    state.intel.known[patrol.id] = { ...last, kind: patrol.kind, day: 7, men: 9, dir: 'este' };
  }
  if (id === 'community') {
    const { ribeira, penedo, souto } = state.communities;
    Object.assign(ribeira, { trust: 88, fear: 18, posture: 'comprometida',
      situation: 'tributada', due: { food: 6, day: 12 } });
    Object.assign(penedo, { trust: 30, fear: 55, posture: 'receosa', situation: 'castigada', until: 14 });
    Object.assign(souto, { situation: 'queimada', families: 0, food: 0 });
    state.villages[souto.settlement].burnt = true;
    // Fonte retains the collaborating posture from the original save.
  }
  return state;
}
